style.css:
/* =====================================================
   WORKING CYBERPUNK FUTURE THEME (STYLISH SAFE)
   ===================================================== */

:root {
  --bg-main: #05060d;
  --glass: rgba(255,255,255,0.06);
  --neon-cyan: #00f6ff;
  --neon-pink: #ff2fdc;
  --text-main: #eaf0ff;
  --border-glass: rgba(255,255,255,0.15);
}

/* BASE */
body {
  background:
    radial-gradient(circle at top, #0c1026, var(--bg-main));
  color: var(--text-main) !important;
  font-family: "Inter","Segoe UI",system-ui,sans-serif;
}

/* GLASS PANELS */
div, section, article, header, footer, nav, main {
  background: var(--glass) !important;
  backdrop-filter: blur(14px);
  border: 1px solid var(--border-glass);
  border-radius: 14px;
}

/* NEON TEXT */
h1, h2, h3 {
  color: #fff !important;
  text-shadow:
    0 0 8px var(--neon-cyan),
    0 0 16px var(--neon-pink);
}

/* SAFE GLITCH (NO data-text REQUIRED) */
h1, h2, h3 {
  animation: glitch 3s infinite;
}

@keyframes glitch {
  0%   { text-shadow: 0 0 8px var(--neon-cyan); }
  20%  { text-shadow: 2px 0 var(--neon-pink), -2px 0 var(--neon-cyan); }
  40%  { text-shadow: -2px 0 var(--neon-pink), 2px 0 var(--neon-cyan); }
  100% { text-shadow: 0 0 8px var(--neon-cyan); }
}

/* LINKS */
a {
  color: var(--neon-cyan) !important;
}
a:hover {
  text-shadow: 0 0 10px var(--neon-cyan);
}

/* BUTTONS */
button,
input[type="button"],
input[type="submit"] {
  background: linear-gradient(135deg, var(--neon-cyan), var(--neon-pink));
  color: #000 !important;
  border: none;
  border-radius: 10px;
  padding: 8px 16px;
  cursor: pointer;
  box-shadow: 0 0 16px var(--neon-cyan);
}
button:hover {
  box-shadow: 0 0 30px var(--neon-pink);
  transform: scale(1.05);
}

/* HOVER NEON (SAFE) */
div:hover,
section:hover,
article:hover {
  box-shadow:
    0 0 20px rgba(0,246,255,0.4),
    0 0 40px rgba(255,47,220,0.2);
}

/* INPUTS */
input, textarea, select {
  background: rgba(5,10,30,0.85) !important;
  color: var(--text-main) !important;
  border: 1px solid var(--neon-cyan);
  border-radius: 10px;
}

/* CRT SCANLINES (WORKING) */
body::after {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    repeating-linear-gradient(
      to bottom,
      rgba(255,255,255,0.04),
      rgba(255,255,255,0.04) 1px,
      transparent 1px,
      transparent 3px
    );
  z-index: 9999;
}

/* SCREEN FLICKER */
body {
  animation: flicker 6s infinite;
}
@keyframes flicker {
  0%,100% { opacity: 1; }
  50% { opacity: 0.97; }
}

/* SCROLLBAR */
::-webkit-scrollbar {
  width: 8px;
}
::-webkit-scrollbar-thumb {
  background: linear-gradient(var(--neon-cyan), var(--neon-pink));
  border-radius: 10px;
}
